//! Runtime support for the NPC scripts generated by `tools/scripts-import/convert_npcs.py`.
#![allow(dead_code)]

use script_sdk::{Context, Function, Request, Value, Variable, VariableScope};

/// Raised by `end`/`close`: unwinds every `callsub` and `callfunc` frame and is not an error.
pub const END: &str = "\u{0}end";

pub fn n(value: i32) -> Value {
    Value::Number(value)
}

pub fn s(value: &str) -> Value {
    Value::String(value.into())
}

pub fn finish(result: Result<Value, String>) -> Result<(), String> {
    match result {
        Ok(_) => Ok(()),
        Err(error) if error == END => Ok(()),
        Err(error) => Err(error),
    }
}

pub fn op(left: Value, operator: &str, right: Value) -> Result<Value, String> {
    if let (Value::String(a), Value::String(b)) = (&left, &right) {
        let ordering = match operator {
            "<" => Some(a < b),
            ">" => Some(a > b),
            "<=" => Some(a <= b),
            ">=" => Some(a >= b),
            _ => None,
        };
        if let Some(result) = ordering {
            return Ok(Value::Number(i32::from(result)));
        }
    }
    if matches!(operator, "==" | "!=") && left.is_number() != right.is_number() {
        let equal = left.text() == right.text();
        return Ok(Value::Number(i32::from(equal == (operator == "=="))));
    }
    left.binary(operator, right)
}

pub fn eq(left: &Value, right: &Value) -> bool {
    left == right || (left.is_number() != right.is_number() && left.text() == right.text())
}

pub fn constant(ctx: &Context, name: &str) -> Result<Value, String> {
    ctx.constant(name)
}

fn scope_of(name: &str) -> (VariableScope, &str) {
    if let Some(rest) = name.strip_prefix("##") {
        (VariableScope::Account, rest)
    } else if let Some(rest) = name.strip_prefix('#') {
        (VariableScope::Account, rest)
    } else if let Some(rest) = name.strip_prefix("$@") {
        (VariableScope::ServerTemporary, rest)
    } else if let Some(rest) = name.strip_prefix('$') {
        (VariableScope::Server, rest)
    } else if let Some(rest) = name.strip_prefix('@') {
        (VariableScope::CharacterTemporary, rest)
    } else if let Some(rest) = name.strip_prefix('.') {
        (VariableScope::NpcInstance, rest)
    } else {
        (VariableScope::Character, name)
    }
}

fn coerce(name: &str, value: Value) -> Result<Value, String> {
    match (name.ends_with('$'), value) {
        (true, Value::Number(number)) => Ok(Value::String(number.to_string())),
        (false, Value::String(text)) => Ok(Value::Number(text.trim().parse().unwrap_or(0))),
        (_, value) => Ok(value),
    }
}

pub fn get(ctx: &Context, name: &str) -> Result<Value, String> {
    get_at(ctx, name, &n(0))
}

pub fn get_at(ctx: &Context, name: &str, index: &Value) -> Result<Value, String> {
    let index = u32::try_from(index.number_value()?).map_err(|_| "Negative array index")?;
    let (scope, stripped) = scope_of(name);
    if index == 0 && matches!(scope, VariableScope::Character) {
        return ctx.read(name);
    }
    ctx.request(Request::VariableRead { scope, name: stripped.into(), index })
}

pub fn set(ctx: &Context, name: &str, value: Value) -> Result<(), String> {
    set_at(ctx, name, &n(0), value)
}

pub fn set_at(ctx: &Context, name: &str, index: &Value, value: Value) -> Result<(), String> {
    let index = u32::try_from(index.number_value()?).map_err(|_| "Negative array index")?;
    let (scope, stripped) = scope_of(name);
    let value = coerce(name, value)?;
    if index == 0 && matches!(scope, VariableScope::Character | VariableScope::CharacterTemporary | VariableScope::Account | VariableScope::Server | VariableScope::ServerTemporary) {
        return ctx.write(name, value);
    }
    ctx.request(Request::VariablesWrite(vec![Variable { scope, name: stripped.into(), index, value }])).map(|_| ())
}

fn default_value(string: bool) -> Value {
    if string { s("") } else { n(0) }
}

pub fn local_get(array: &[Value], index: &Value, string: bool) -> Value {
    index.number_value().ok().and_then(|index| usize::try_from(index).ok()).and_then(|index| array.get(index).cloned()).unwrap_or_else(|| default_value(string))
}

pub fn local_set(array: &mut Vec<Value>, index: &Value, value: Value, string: bool) {
    let Some(index) = index.number_value().ok().and_then(|index| usize::try_from(index).ok()) else { return };
    if index > 65_535 {
        return;
    }
    if array.len() <= index {
        array.resize(index + 1, default_value(string));
    }
    array[index] = value;
}

pub fn arg(args: &[Value], index: i32, default: Value) -> Value {
    usize::try_from(index).ok().and_then(|index| args.get(index).cloned()).unwrap_or(default)
}

/// `select` and `menu`: the options are `:` separated, empty ones are skipped, the answer is 1-based.
pub fn select(ctx: &Context, options: &[&str]) -> Result<i32, String> {
    let options: Vec<Value> = options.iter().flat_map(|option| option.split(':')).filter(|option| !option.is_empty()).map(s).collect();
    let selected = ctx.call(Function::Select, options.clone())?.number_value()?;
    if selected < 1 || selected as usize > options.len() {
        return Err("Conversation cancelled".into());
    }
    Ok(selected)
}

pub fn select_text(ctx: &Context, options: &[Value]) -> Result<i32, String> {
    let joined = options.iter().map(Value::text).collect::<Vec<_>>().join(":");
    select(ctx, &[joined.as_str()])
}

pub fn strlen(value: Value) -> Result<Value, String> {
    Ok(n(value.text().chars().count() as i32))
}

pub fn substr(value: Value, start: Value, end: Value) -> Result<Value, String> {
    let text: Vec<char> = value.text().chars().collect();
    let (start, end) = (start.number_value()?, end.number_value()?);
    if start < 0 || end < start || start as usize >= text.len() {
        return Ok(s(""));
    }
    let end = (end as usize).min(text.len() - 1);
    Ok(Value::String(text[start as usize..=end].iter().collect()))
}

pub fn charat(value: Value, index: Value) -> Result<Value, String> {
    let index = index.number_value()?;
    Ok(Value::String(usize::try_from(index).ok().and_then(|index| value.text().chars().nth(index)).map(String::from).unwrap_or_default()))
}

pub fn atoi(value: Value) -> Result<Value, String> {
    Ok(n(value.text().trim().parse().unwrap_or(0)))
}

/// Case-insensitive "contains".
pub fn compare(haystack: Value, needle: Value) -> Result<Value, String> {
    Ok(n(i32::from(haystack.text().to_lowercase().contains(&needle.text().to_lowercase()))))
}

pub fn strtolower(value: Value) -> Result<Value, String> {
    Ok(Value::String(value.text().to_lowercase()))
}

pub fn strtoupper(value: Value) -> Result<Value, String> {
    Ok(Value::String(value.text().to_uppercase()))
}

/// `getarraysize` of a stored variable: one past the last entry that is not zero or empty.
pub fn array_size(ctx: &Context, name: &str) -> Result<Value, String> {
    let mut size = 0;
    for index in 0..256 {
        if get_at(ctx, name, &n(index))?.truthy() {
            size = index + 1;
        }
    }
    Ok(n(size))
}

/// `getpartymember`: fills `$@partymembername$`, `$@partymembercid` or `$@partymemberaid` and `$@partymembercount`.
pub fn party_members(ctx: &Context, party: Value, kind: Value) -> Result<(), String> {
    let kind_number = kind.number_value()?;
    let Value::Array(members) = ctx.call(Function::GetPartyMember, vec![party, kind])? else {
        return Err("Invalid party member list".into());
    };
    let array = match kind_number {
        1 => "$@partymembercid",
        2 => "$@partymemberaid",
        _ => "$@partymembername$",
    };
    set(ctx, "$@partymembercount", n(members.len() as i32))?;
    for (index, member) in members.into_iter().enumerate() {
        set_at(ctx, array, &n(index as i32), member)?;
    }
    Ok(())
}

/// `sprintf` with `%d`, `%i`, `%s` and `%%`, honouring the `-`, `0` flags and a width.
pub fn sprintf(format: Value, arguments: Vec<Value>) -> Result<Value, String> {
    let format = format.text();
    let mut remaining = arguments.into_iter();
    let mut output = String::new();
    let mut characters = format.chars().peekable();
    while let Some(character) = characters.next() {
        if character != '%' {
            output.push(character);
            continue;
        }
        let (mut left, mut zero, mut width) = (false, false, 0usize);
        while let Some(&flag) = characters.peek() {
            match flag {
                '-' => left = true,
                '0' => zero = true,
                _ => break,
            }
            characters.next();
        }
        while let Some(digit) = characters.peek().and_then(|digit| digit.to_digit(10)) {
            width = width * 10 + digit as usize;
            characters.next();
        }
        let text = match characters.next() {
            Some('%') => {
                output.push('%');
                continue;
            }
            Some('d' | 'i') => remaining.next().map(|value| value.number_value()).transpose()?.unwrap_or(0).to_string(),
            Some('s') => remaining.next().map(|value| value.text()).unwrap_or_default(),
            _ => return Err("Unsupported sprintf format".into()),
        };
        let padding = width.saturating_sub(text.chars().count());
        match (left, zero) {
            (true, _) => output.extend([text.as_str(), &" ".repeat(padding)]),
            (false, true) => output.extend([&"0".repeat(padding), text.as_str()]),
            (false, false) => output.extend([&" ".repeat(padding), text.as_str()]),
        }
    }
    Ok(Value::String(output))
}

pub fn implode(array: &[Value], delimiter: Value) -> Result<Value, String> {
    Ok(Value::String(array.iter().map(Value::text).collect::<Vec<_>>().join(&delimiter.text())))
}

pub fn explode(value: Value, delimiter: Value) -> Result<Vec<Value>, String> {
    let (text, delimiter) = (value.text(), delimiter.text());
    if delimiter.is_empty() {
        return Ok(vec![Value::String(text)]);
    }
    Ok(text.split(delimiter.as_str()).map(s).collect())
}

pub fn countstr(value: Value, needle: Value) -> Result<Value, String> {
    let needle = needle.text();
    Ok(n(if needle.is_empty() { 0 } else { value.text().matches(needle.as_str()).count() as i32 }))
}

pub fn delchar(value: Value, characters: Value) -> Result<Value, String> {
    let removed = characters.text();
    Ok(Value::String(value.text().chars().filter(|character| !removed.contains(*character)).collect()))
}

/// `npcskill`: the NPC casts a support skill on the attached player with its own level and intelligence.
pub fn npc_skill(ctx: &Context, skill: Value, level: Value, stat: Value, npc_level: Value) -> Result<(), String> {
    let (level, stat, npc_level) = (level.number_value()?, stat.number_value()?, npc_level.number_value()?);
    match skill.text().to_ascii_uppercase().as_str() {
        "AL_HEAL" => {
            let hp = (npc_level + stat) / 8 * (4 + 8 * level);
            ctx.call(Function::Heal, vec![n(hp), n(0)])?;
        }
        buff @ ("AL_BLESSING" | "AL_INCAGI") => {
            let status = if buff == "AL_BLESSING" { "SC_BLESSING" } else { "SC_INCREASEAGI" };
            ctx.call(Function::StartStatus, vec![ctx.constant(status)?, n(40_000 + 20_000 * level), n(level)])?;
        }
        other => return Err(format!("npcskill does not support {other}")),
    }
    Ok(())
}
